import React, { useState } from 'react';
import { 
  User, Mail, Phone, Globe, 
  Save, X, Edit2, Check
} from 'lucide-react';

const AccountSettings = () => {
  const [editMode, setEditMode] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({
    fullName: 'Enzo Admin',
    email: 'enzo.admin@example.com',
    phone: '+33 6 12 34 56 78',
    language: 'fr',
    timezone: 'Europe/Paris',
    bio: 'Administrateur système avec 5 ans d\'expérience dans la gestion de plateformes SaaS.'
  });

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setEditMode(false);
    }, 1000);
  };

  const handleCancel = () => {
    setEditMode(false);
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center space-x-3">
          <div className="h-12 w-12 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
            <User className="h-6 w-6 text-white" />
          </div>
          <div>
            <h3 className="text-lg font-bold text-neutral-900 dark:text-white">Informations du compte</h3>
            <p className="text-sm text-neutral-600 dark:text-neutral-400">Gérez vos informations personnelles</p>
          </div>
        </div>
        {!editMode ? (
          <button
            onClick={() => setEditMode(true)}
            className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300"
          >
            <Edit2 className="h-4 w-4" />
            <span className="text-sm font-medium">Modifier</span>
          </button>
        ) : (
          <div className="flex items-center space-x-2">
            <button
              onClick={handleCancel}
              className="flex items-center space-x-2 px-4 py-2.5 rounded-xl border border-neutral-300 dark:border-neutral-700 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
            >
              <X className="h-4 w-4" />
              <span className="text-sm font-medium">Annuler</span>
            </button>
            <button
              onClick={handleSave}
              disabled={isSaving}
              className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/25 transition-all duration-300 disabled:opacity-50"
            >
              {isSaving ? (
                <>
                  <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"></div>
                  <span className="text-sm font-medium">Sauvegarde...</span>
                </>
              ) : (
                <>
                  <Save className="h-4 w-4" />
                  <span className="text-sm font-medium">Sauvegarder</span>
                </>
              )}
            </button>
          </div>
        )}
      </div>

      {/* Form */}
      <div className="space-y-6">
        {/* Nom complet */}
        <div className="group">
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Nom complet
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <User className="h-5 w-5 text-neutral-400 group-hover:text-primary-500 transition-colors" />
            </div>
            <input
              type="text"
              value={formData.fullName}
              onChange={(e) => setFormData({...formData, fullName: e.target.value})}
              disabled={!editMode}
              className={`pl-11 pr-4 py-3 w-full rounded-xl border-2 transition-all duration-300 ${
                editMode 
                  ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                  : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
              }`}
            />
          </div>
        </div>

        {/* Email et Téléphone */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="group">
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Adresse email
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Mail className="h-5 w-5 text-neutral-400 group-hover:text-primary-500 transition-colors" />
              </div>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
                disabled={!editMode}
                className={`pl-11 pr-4 py-3 w-full rounded-xl border-2 transition-all duration-300 ${
                  editMode 
                    ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                    : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
                }`}
              />
            </div>
          </div>

          <div className="group">
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Téléphone
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Phone className="h-5 w-5 text-neutral-400 group-hover:text-primary-500 transition-colors" />
              </div>
              <input
                type="tel"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
                disabled={!editMode}
                className={`pl-11 pr-4 py-3 w-full rounded-xl border-2 transition-all duration-300 ${
                  editMode 
                    ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                    : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
                }`}
              />
            </div>
          </div>
        </div>

        {/* Langue et Timezone */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="group">
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Langue
            </label>
            <div className="relative">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Globe className="h-5 w-5 text-neutral-400 group-hover:text-primary-500 transition-colors" />
              </div>
              <select
                value={formData.language}
                onChange={(e) => setFormData({...formData, language: e.target.value})}
                disabled={!editMode}
                className={`pl-11 pr-4 py-3 w-full rounded-xl border-2 appearance-none transition-all duration-300 ${
                  editMode 
                    ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                    : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
                }`}
              >
                <option value="fr">Français</option>
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="de">Deutsch</option>
              </select>
            </div>
          </div>

          <div className="group">
            <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
              Fuseau horaire
            </label>
            <select
              value={formData.timezone}
              onChange={(e) => setFormData({...formData, timezone: e.target.value})}
              disabled={!editMode}
              className={`px-4 py-3 w-full rounded-xl border-2 appearance-none transition-all duration-300 ${
                editMode 
                  ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                  : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
              }`}
            >
              <option value="Europe/Paris">Paris (GMT+1)</option>
              <option value="Europe/London">London (GMT+0)</option>
              <option value="America/New_York">New York (GMT-5)</option>
              <option value="Asia/Tokyo">Tokyo (GMT+9)</option>
            </select>
          </div>
        </div>

        {/* Bio */}
        <div className="group">
          <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
            Bio
          </label>
          <textarea
            value={formData.bio}
            onChange={(e) => setFormData({...formData, bio: e.target.value})}
            disabled={!editMode}
            rows="3"
            className={`px-4 py-3 w-full rounded-xl border-2 transition-all duration-300 resize-none ${
              editMode 
                ? 'border-primary-500/50 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white focus:ring-2 focus:ring-primary-500/20'
                : 'border-transparent bg-neutral-50 dark:bg-neutral-800/30 text-neutral-600 dark:text-neutral-400'
            }`}
          />
        </div>
      </div>
    </div>
  );
};

export default AccountSettings;
